-- procedimientos_documentados_requeridos
update public.fields set verification_status='verified_against_standard', verification_quote='La documentación del sistema de gestión de la calidad debe incluir: [...] c) los procedimientos documentados y los registros requeridos por esta Norma Internacional, y | NOTA 1 Cuando aparece el término "procedimiento documentado" dentro de esta Norma Internacional, significa que el procedimiento sea establecido, documentado, implementado y mantenido. Un solo documento puede incluir los requisitos para uno o más procedimientos. Un requisito relativo a un procedimiento documentado puede cubrirse con más de un documento. — printed p.3', verification_note='md-verified 2026-09-05 (§4.2.1 c); NOTA 1, printed p.3) [VC] — the field description names six documented procedures (4.2.3, 4.2.4, 8.2.2, 8.3, 8.5.2, 8.5.3) - that enumeration is DERIVED by collecting the six clauses that each print "debe establecerse un procedimiento documentado"; the standard prints neither the list nor the number six', verified_at=now() where id='f939c21f-b921-40ce-8b14-e89c6810394e' and verification_status not in ('verified_against_standard','corrected');
-- control_documentos
update public.fields set verification_status='verified_against_standard', verification_quote='Los documentos requeridos por el sistema de gestión de la calidad deben controlarse. Los registros son un tipo especial de documento y deben controlarse de acuerdo con los requisitos citados en el apartado 4.2.4. | Debe establecerse un procedimiento documentado que defina los controles necesarios para: a) aprobar los documentos en cuanto a su adecuación antes de su emisión, b) revisar y actualizar los documentos cuando sea necesario y aprobarlos nuevamente, [...] g) prevenir el uso no intencionado de documentos obsoletos, y aplicarles una identificación adecuada en el caso de que se mantengan por cualquier razón. — printed p.3', verification_note='md-verified 2026-09-05 (§4.2.3, printed p.3) [VC]', verified_at=now() where id='639ffdac-f337-4e38-b103-af32629485ce' and verification_status not in ('verified_against_standard','corrected');
