-- infraestructura_provista
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar, proporcionar y mantener la infraestructura necesaria para lograr la conformidad con los requisitos del producto. La infraestructura incluye, cuando sea aplicable: a) edificios, espacio de trabajo y servicios asociados, b) equipo para los procesos (tanto hardware como software), y c) servicios de apoyo (tales como transporte, comunicación o sistemas de información). — printed p.7', verification_note='md-verified 2026-09-05 (§6.3, printed p.7) [VC]', verified_at=now() where id='f328b70d-64d4-4090-bb9e-0040b49ffb7a' and verification_status not in ('verified_against_standard','corrected');
