-- planificacion_realizacion_producto
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe planificar y desarrollar los procesos necesarios para la realización del producto. La planificación de la realización del producto debe ser coherente con los requisitos de los otros procesos del sistema de gestión de la calidad (véase 4.1). | Durante la planificación de la realización del producto, la organización debe determinar, cuando sea apropiado, lo siguiente: a) los objetivos de la calidad y los requisitos para el producto, [...] d) los registros que sean necesarios para proporcionar evidencia de que los procesos de realización y el producto resultante cumplen los requisitos (véase 4.2.4). — printed p.8', verification_note='md-verified 2026-09-05 (§7.1, printed p.8) [VC]', verified_at=now() where id='40045d18-b43d-4678-8e14-a10b173b7202' and verification_status not in ('verified_against_standard','corrected');
-- requisitos_producto_determinados
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar: a) los requisitos especificados por el cliente, incluyendo los requisitos para las actividades de entrega y las posteriores a la misma, b) los requisitos no establecidos por el cliente pero necesarios para el uso especificado o para el uso previsto, cuando sea conocido, c) los requisitos legales y reglamentarios aplicables al producto, y d) cualquier requisito adicional que la organización considere necesario. — printed p.8', verification_note='md-verified 2026-09-05 (§7.2.1, printed p.8) [VC]', verified_at=now() where id='83fc090d-2364-45bf-b48a-b705d42b97d8' and verification_status not in ('verified_against_standard','corrected');
-- revision_requisitos_producto
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe revisar los requisitos relacionados con el producto. Esta revisión debe efectuarse antes de que la organización se comprometa a proporcionar un producto al cliente (por ejemplo, envío de ofertas, aceptación de contratos o pedidos, aceptación de cambios en los contratos o pedidos) y debe asegurarse de que: a) están definidos los requisitos del producto, b) están resueltas las diferencias existentes entre los requisitos del contrato o pedido y los expresados previamente, y c) la organización tiene la capacidad para cumplir con los requisitos definidos. | Deben mantenerse registros de los resultados de la revisión y de las acciones originadas por la misma (véase 4.2.4). — printed p.8', verification_note='md-verified 2026-09-05 (§7.2.2, printed p.8) [VC]', verified_at=now() where id='fb7b8456-6577-4c45-8c9b-50ade6e94f7e' and verification_status not in ('verified_against_standard','corrected');
-- comunicacion_cliente
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar e implementar disposiciones eficaces para la comunicación con los clientes, relativas a: a) la información sobre el producto, b) las consultas, contratos o atención de pedidos, incluyendo las modificaciones, y c) la retroalimentación del cliente, incluyendo sus quejas. — printed p.8', verification_note='md-verified 2026-09-05 (§7.2.3, printed p.8) [VC]', verified_at=now() where id='43af6670-011b-4816-8b23-62e827634299' and verification_status not in ('verified_against_standard','corrected');
-- planificacion_diseno_desarrollo
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe planificar y controlar el diseño y desarrollo del producto. Durante la planificación del diseño y desarrollo la organización debe determinar: a) las etapas del diseño y desarrollo, b) la revisión, verificación y validación, apropiadas para cada etapa del diseño y desarrollo, y c) las responsabilidades y autoridades para el diseño y desarrollo. | La organización debe gestionar las interfaces entre los diferentes grupos involucrados en el diseño y desarrollo para asegurarse de una comunicación eficaz y una clara asignación de responsabilidades. — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.1, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='6433884f-4adf-4200-a394-970302b32e42' and verification_status not in ('verified_against_standard','corrected');
-- entradas_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='Deben determinarse los elementos de entrada relacionados con los requisitos del producto y mantenerse registros (véase 4.2.4). Estos elementos de entrada deben incluir: a) los requisitos funcionales y de desempeño, b) los requisitos legales y reglamentarios aplicables, c) la información proveniente de diseños previos similares, cuando sea aplicable, y d) cualquier otro requisito esencial para el diseño y desarrollo. | Los elementos de entrada deben revisarse para comprobar que sean adecuados. Los requisitos deben estar completos, sin ambigüedades y no deben ser contradictorios. — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.2, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='d2d113eb-d240-4cbe-8074-ecbbde0fc40f' and verification_status not in ('verified_against_standard','corrected');
-- resultados_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='Los resultados del diseño y desarrollo deben proporcionarse de manera adecuada para la verificación respecto a los elementos de entrada para el diseño y desarrollo, y deben aprobarse antes de su liberación. | Los resultados del diseño y desarrollo deben: a) cumplir los requisitos de los elementos de entrada para el diseño y desarrollo, b) proporcionar información apropiada para la compra, la producción y la prestación del servicio, c) contener o hacer referencia a los criterios de aceptación del producto, y d) especificar las características del producto que son esenciales para el uso seguro y correcto. — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.3, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='92637ae7-ce51-4614-aa79-c20770e01c5d' and verification_status not in ('verified_against_standard','corrected');
-- revision_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='En las etapas adecuadas, deben realizarse revisiones sistemáticas del diseño y desarrollo de acuerdo con lo planificado (véase 7.3.1) para: a) evaluar la capacidad de los resultados de diseño y desarrollo para cumplir los requisitos, e b) identificar cualquier problema y proponer las acciones necesarias. | Los participantes en dichas revisiones deben incluir representantes de las funciones relacionadas con la(s) etapa(s) de diseño y desarrollo que se está(n) revisando. Deben mantenerse registros de los resultados de las revisiones y de cualquier acción necesaria (véase 4.2.4). — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.4, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='6230825b-211f-4a5e-ba6e-b8f920b689f5' and verification_status not in ('verified_against_standard','corrected');
-- verificacion_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='Se debe realizar la verificación, de acuerdo con lo planificado (véase 7.3.1), para asegurarse de que los resultados del diseño y desarrolio cumplen los requisitos de los elementos de entrada del diseño y desarrollo. Deben mantenerse registros de los resultados de la verificación y de cualquier acción que sea necesaria (véase 4.2.4). — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.5, printed p.9) [VC] — quoted verbatim incl. the transcript OCR defect "desarrolio" (for "desarrollo"); Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='713eccd5-15f1-4f7e-90a2-695110429280' and verification_status not in ('verified_against_standard','corrected');
-- validacion_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='Se debe realizar la validación del diseño y desarrollo de acuerdo con lo planificado (véase 7.3.1) para asegurarse de que el producto resultante es capaz de satisfacer los requisitos para su aplicación especificada o uso previsto, cuando sea conocido. Siempre que sea factible, la validación debe completarse antes de la entrega o implementación del producto. Deben mantenerse registros de los resultados de la validación y de cualquier acción que sea necesaria (véase 4.2.4). — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.6, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='43fc17f5-0d87-45fc-aa47-515012d6d0ce' and verification_status not in ('verified_against_standard','corrected');
-- control_cambios_diseno
update public.fields set verification_status='verified_against_standard', verification_quote='Los cambios del diseño y desarrollo deben identificarse y deben mantenerse registros. Los cambios deben revisarse, verificarse y validarse, según sea apropiado, y aprobarse antes de su implementación. La revisión de los cambios del diseño y desarrollo debe incluir la evaluación del efecto de los cambios en las partes constitutivas y en el producto ya entregado. Deben mantenerse registros de los resultados de la revisión de los cambios y de cualquier acción que sea necesaria (véase 4.2.4). — printed p.9', verification_note='md-verified 2026-09-05 (§7.3.7, printed p.9) [VC] — Chapter 7 requirement - excludable under 1.2', verified_at=now() where id='d788127d-0dc9-4184-8ba4-dcd3a638eadc' and verification_status not in ('verified_against_standard','corrected');
-- proceso_compras
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe asegurarse de que el producto adquirido cumple los requisitos de compra especificados. El tipo y el grado del control aplicado al proveedor y al producto adquirido debe depender del impacto del producto adquirido en la posterior realización del producto o sobre el producto final. | La organización debe evaluar y seleccionar los proveedores en función de su capacidad para suministrar productos de acuerdo con los requisitos de la organización. Deben establecerse los criterios para la selección, la evaluación y la re-evaluación. Deben mantenerse los registros de los resultados de las evaluaciones y de cualquier acción necesaria que se derive de las mismas (véase 4.2.4). — printed p.11', verification_note='md-verified 2026-09-05 (§7.4.1, printed p.11) [VC]', verified_at=now() where id='3ca7d72b-e658-4d9e-80bf-938e57989084' and verification_status not in ('verified_against_standard','corrected');
-- informacion_compras
update public.fields set verification_status='verified_against_standard', verification_quote='La información de las compras debe describir el producto a comprar, incluyendo, cuando sea apropiado: a) Ios requisitos para la aprobación del producto, procedimientos, procesos y equipos, b) los requisitos para la calificación del personal, y c) los requisitos del sistema de gestión de la calidad. | La organización debe aseguirarse de la adecuación de los requisitos de compra especificados antes de comunicárselos al proveedor. — printed p.11', verification_note='md-verified 2026-09-05 (§7.4.2, printed p.11) [VC] — quoted verbatim incl. the transcript OCR defects "Ios requisitos" (for "los") and "aseguirarse" (for "asegurarse")', verified_at=now() where id='2a936cdc-7a46-4e71-b707-39b7b8b830a2' and verification_status not in ('verified_against_standard','corrected');
-- verificacion_productos_comprados
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe establecer e implementar la inspección u otras actividades necesarias para asegurarse de que el producto comprado cumple los requisitos de compra especificados. | Cuando la organización o su cliente quieran llevar a cabo la verificación en las instalaciones del proveedor, la organización debe establecer en la información de compra las disposiciones para la verificación pretendida y el método para la liberación del producto. — printed p.11', verification_note='md-verified 2026-09-05 (§7.4.3, printed p.11) [VC]', verified_at=now() where id='e6cae208-449f-4c00-83ba-68574f05ba66' and verification_status not in ('verified_against_standard','corrected');
-- control_produccion
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe planificar y llevar a cabo la producción y la prestación del servicio bajo condiciones controladas. Las condiciones controladas deben incluir, cuando sea aplicable: a) la disponibilidad de información que describa las características del producto, b) la disponibilidad de instrucciones de trabajo, cuando sea necesario, c) el uso del equipo apropiado, d) la disponibilidad y uso de equipos de seguimiento y medición, e) la implementación del seguimiento y de la medición, y f) la implementación de actividades de liberación, entrega y posteriores a la entrega del producto. — printed p.12', verification_note='md-verified 2026-09-05 (§7.5.1, printed p.12) [VC]', verified_at=now() where id='34e5db49-574f-4d45-9bdf-9f555f442ceb' and verification_status not in ('verified_against_standard','corrected');
-- validacion_procesos_produccion
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe validar todo proceso de producción y de prestación del servicio cuando los productos resultantes no pueden verificarse mediante seguimiento o medición posteriores y, como consecuencia, las deficiencias aparecen únicamente después de que el producto esté siendo utilizado o se haya prestado el servicio. | La validación debe demostrar la capacidad de estos procesos para alcanzar los resultados planificados. — printed p.12', verification_note='md-verified 2026-09-05 (§7.5.2, printed p.12) [VC] — duty is scoped: it applies only to processes whose output "no pueden verificarse mediante seguimiento o medición posteriores"', verified_at=now() where id='46feb5f8-a9f5-47ab-9a21-2a16d7fc092b' and verification_status not in ('verified_against_standard','corrected');
-- identificacion_trazabilidad
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando sea apropiado, la organización debe identificar el próducto por medios adecuados, a través de toda la realización del producto. | Cuando la trazabilidad sea un requisito, la organización debe controlar la identificación única del producto y mantener registros (véase 4.2.4). — printed p.12', verification_note='md-verified 2026-09-05 (§7.5.3, printed p.12) [VC] — quoted verbatim incl. the transcript OCR defect (accented "producto" in line 551 of the md); duty scoped "Cuando sea apropiado" / "Cuando la trazabilidad sea un requisito"', verified_at=now() where id='f6f1f002-a4fa-4fc0-9d46-16fb1ca89ce2' and verification_status not in ('verified_against_standard','corrected');
-- propiedad_cliente
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe cuidar los bienes que son propiedad del cliente mientras estén bajo el control de la organización o estén siendo utilizados por la misma. La organización debe identificar, verificar, proteger y salvaguardar los bienes que son propiedad del cliente suministrados para su utilización o incorporación dentro del producto. Si cualquier bien que sea propiedad del cliente se pierde, deteriora o de algún otro modo se considera inadecuado para su uso, la organización debe informar de ello al cliente y mantener registros (véase 4.2.4). — printed p.12', verification_note='md-verified 2026-09-05 (§7.5.4, printed p.12) [VC] — duty applies only where customer property is under the control of the organisation', verified_at=now() where id='0c34458e-55c4-42a9-b7a7-08cfa66085ae' and verification_status not in ('verified_against_standard','corrected');
-- preservacion_producto
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe preservar el producto durante el proceso interno y la entrega al destino previsto para mantener la conformidad con los requisitos. Según sea aplicable, la preservación debe incluir la identificación, manipulación, embalaje, almacenamiento y protección. La preservación debe aplicarse también a las partes constitutivas de un producto. — printed p.12', verification_note='md-verified 2026-09-05 (§7.5.5, printed p.12) [VC]', verified_at=now() where id='5607d2ce-5fa8-4c5d-94af-ed2b649ba54d' and verification_status not in ('verified_against_standard','corrected');
-- control_equipos_medicion
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar el seguimiento y la medición a realizar y los equipos de seguimiento y medición necesarios para proporcionar la evidencia de la conformidad del producto con los requisitos determinados. | Cuando sea necesario asegurarse de la validez de los resultados, el equipo de medición debe: a) calibrarse o verificarse, o ambos, a intervalos especificados o antes de su utilización, comparado con patrones de medición trazables a patrones de medición internacionales o nacionales; cuando no existan tales patrones debe registrarse la base utilizada para la calibración o la verificación (véase 4.2.4); — printed p.13', verification_note='md-verified 2026-09-05 (§7.6, printed p.13) [VC]', verified_at=now() where id='4710b57d-c8e0-4844-a57a-6b256897fab3' and verification_status not in ('verified_against_standard','corrected');
-- procesos_medicion_planificados
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe planificar e implementar los procesos de seguimiento, medición, análisis y mejora necesarios para: a) demostrar la conformidad con los requisitos del producto, b) asegurarse de la conformidad del sistema de gestión de la calidad, y c) mejorar continuamente la eficacia del sistema de gestión de la calidad. | Esto debe comprender la determinación de los métodos aplicables, incluyendo las técnicas estadisticas, y el alcance de su utilización. — printed p.14', verification_note='md-verified 2026-09-05 (§8.1, printed p.14) [VC]', verified_at=now() where id='3ca7c262-062d-484f-8114-77917ef8e5a2' and verification_status not in ('verified_against_standard','corrected');
-- seguimiento_satisfaccion_cliente
update public.fields set verification_status='verified_against_standard', verification_quote='Como una de las medidas del desempeño del sistema de gestión de la calidad, la organización debe realizar el seguimiento de la información relativa a la percepción del cliente con respecto al cumplimiento de sus requisitos por parte de la organización. Deben determinarse los métodos para obtener y utilizar dicha información. — printed p.14', verification_note='md-verified 2026-09-05 (§8.2.1, printed p.14) [VC]', verified_at=now() where id='94bbaf07-6f35-437d-91a2-de8ab2cdbe9e' and verification_status not in ('verified_against_standard','corrected');
-- auditoria_interna_programa
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe llevar a cabo auditorías internas a intervalos planificados para determinar si el sistema de gestión de la calidad: | Se debe planificar un programa de auditorías tomando en consideración el estado y la importancia de los procesos y las áreas a auditar, así como los resultados de auditorías previas. Se deben definir los criterios de auditoría, el alcance de la misma, su frecuencia y la metodología. La selección de los auditores y la realización de las auditorías deben asegurar la objetividad e imparcialidad del proceso de auditoría. Los auditores no deben auditar su propio trabajo. — printed p.14', verification_note='md-verified 2026-09-05 (§8.2.2, printed p.14) [VC]', verified_at=now() where id='872adbe8-838d-4b37-a72c-7511c5ae0cd3' and verification_status not in ('verified_against_standard','corrected');
-- seguimiento_medicion_procesos
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe aplicar métodos apropiados para el seguimiento, y cuando sea aplicable, la medición de los procesos del sistema de gestión de la calidad. Estos métodos deben demostrar la capacidad de los procesos para alcanzar los resultados planificados. Cuando no se alcancen los resultados planificados, deben llevarse a cabo correcciones y acciones correctivas, según sea conveniente. — printed p.14', verification_note='md-verified 2026-09-05 (§8.2.3, printed p.14) [VC]', verified_at=now() where id='991b844f-affe-4b70-ab68-a5f926c494ef' and verification_status not in ('verified_against_standard','corrected');
-- seguimiento_medicion_producto
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe hacer el seguimiento y medir las características del producto para verificar que se cumplen los requisitos del mismo. Esto debe realizarse en las etapas apropiadas del proceso de realización del producto de acuerdo con las disposiciones planificadas (véase 7.1). Se debe mantener evidencia de la conformidad con los criterios de aceptación. | La liberación del producto y la prestación del servicio al cliente no deben llevarse a cabo hasta que se hayan completado satisfactoriamente las disposiciones planificadas (véase 7.1), a menos que sean aprobados de otra manera por una autoridad pertinente y, cuando corresponda, por el cliente. — printed p.14', verification_note='md-verified 2026-09-05 (§8.2.4, printed p.14) [VC]', verified_at=now() where id='129508e8-e4f6-42b9-b462-a4366930e2e1' and verification_status not in ('verified_against_standard','corrected');
-- analisis_datos
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar, recopilar y analizar los datos apropiados para demostrar la idoneidad y la eficacia del sistema de gestión de la calidad y para evaluar dónde puede realizarse la mejora continua de la eficacia del sistema de gestión de la calidad. Esto debe incluir los datos generados del resultado del seguimiento y medición y de cualesquiera otras fuentes pertinentes. | El análisis de datos debe proporcionar información sobre: a) la satisfacción del cliente (véase 8.2.1), b) la conformidad con los requisitos del producto (véase 8.2.4), [...] d) los proveedores (véase 7.4). — printed p.16', verification_note='md-verified 2026-09-05 (§8.4, printed p.16) [VC]', verified_at=now() where id='eae16811-e217-4d30-8364-e89ac707894b' and verification_status not in ('verified_against_standard','corrected');
-- revision_direccion_realizada
update public.fields set verification_status='verified_against_standard', verification_quote='La alta dirección debe revisar el sistema de gestión de la calidad de la organización, a intervalos planificados, para asegurarse de su conveniencia, adecuación y eficacia continuas. La revisión debe incluir la evaluación de las oportunidades de mejora y la necesidad de efectuar cambios en el sistema de gestión de la calidad, incluyendo la política de la calidad y los objetivos de la calidad. | Deben mantenerse registros de las revisiones por la dirección (véase 4.2.4). — printed p.6', verification_note='md-verified 2026-09-05 (§5.6.1, printed p.6) [VC]', verified_at=now() where id='39122b98-89c4-44ef-86dc-48ac261a07ef' and verification_status not in ('verified_against_standard','corrected');
-- entradas_revision_direccion
update public.fields set verification_status='verified_against_standard', verification_quote='La información de entrada para la revisión por la dirección debe incluir: a) los resultados de auditorías, b) la retroalimentación del cliente, c) el desempeño de los procesos y la conformidad del producto, d) el estado de las acciones correctivas y preventivas, e) las acciones de seguimiento de revisiones por la dirección previas, f) los cambios que podrían afectar al sistema de gestión de la calidad, y g) las recomendaciones para la mejora. — printed p.6', verification_note='md-verified 2026-09-05 (§5.6.2, printed p.6) [VC]', verified_at=now() where id='f81a81c9-08a3-46a2-8051-e37705d4af7d' and verification_status not in ('verified_against_standard','corrected');
-- resultados_revision_direccion
update public.fields set verification_status='verified_against_standard', verification_quote='Los resultados de la revisión por la dirección deben incluir todas las decisiones y acciones relacionadas con: a) la mejora de la eficacia del sistema de gestión de la calidad y sus procesos, b) la mejora del producto en relación con los requisitos del cliente, y c) las necesidades de recursos. — printed p.6', verification_note='md-verified 2026-09-05 (§5.6.3, printed p.6) [VC]', verified_at=now() where id='22506573-fa9a-4643-9574-a3b691d8382c' and verification_status not in ('verified_against_standard','corrected');
-- control_producto_no_conforme
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe asegurarse de que el producto que no sea conforme con los requisitos del producto, se identifica y controla para prevenir su uso o entrega no intencionados. Se debe establecer un procedimiento documentado para definir los controles y las responsabilidades y autoridades relacionadas para tratar el producto no conforme. | Cuando se corrige un producto no conforme, debe someterse a una nueva verificación para demostrar su conformidad con los requisitos. | Se deben mantener registros (véase 4.2.4) de la naturaleza de las no conformidades y de cualquier acción tomada posteriormente, incluyendo las concesiones que se hayan obtenido. — printed p.15', verification_note='md-verified 2026-09-05 (§8.3, printed p.15) [VC]', verified_at=now() where id='8dd3bf71-b7e3-48c4-b5ed-68bc27681123' and verification_status not in ('verified_against_standard','corrected');
-- tratamiento_no_conformidad
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando sea aplicable, la organización debe tratar los productos no conformes mediante una o más de las siguientes maneras: a) tomando acciones para eliminar la no conformidad detectada; b) autorizando su uso, liberación o aceptación bajo concesión por una autoridad pertinente y, cuando sea aplicable, por el cliente; c) tomando acciones para impedir su uso o aplicación prevista originalmente; d) tomando acciones apropiadas a los efectos, reales o potenciales, de la no conformidad cuando se detecta un producto no conforme después de su entrega o cuando ya ha comenzado su uso. — printed p.15', verification_note='md-verified 2026-09-05 (§8.3 a)-d), printed p.15) [VC] — the standard says "una o mas de las siguientes maneras" - the encoded single-select enum cannot express the printed "una o mas"; staged for ratification', verified_at=now() where id='e11b7d12-e6cf-4776-b629-3c62dae4813b' and verification_status not in ('verified_against_standard','corrected');
-- mejora_continua
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe mejorar continuamente la eficacia del sistema de gestión de la calidad mediante el uso de la política de la calidad, los objetivos de la calidad, los resultados de las auditorías, el análisis de datos, las acciones correctivas y preventivas y la revisión por la dirección. — printed p.16', verification_note='md-verified 2026-09-05 (§8.5.1, printed p.16) [VC]', verified_at=now() where id='9fbc3ca9-e1ef-4da0-9829-da7dda9494b2' and verification_status not in ('verified_against_standard','corrected');
-- accion_correctiva
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe tomar acciones para eliminar las causas de las no conformidades con objeto de prevenir que vuelvan a ocurrir. Las acciones correctivas deben ser apropiadas a los efectos de las no conformidades encontradas. | Debe establecerse un procedimiento documentado para definir los requisitos para: a) revisar las no conformidades (incluyendo las quejas de los clientes), b) determinar las causas de las no conformidades, c) evaluar la necesidad de adoptar acciones para asegurarse de que las no conformidades no vuelvan a ocurrir, d) determinar e implementar las acciones necesarias, e) registrar los resultados de las acciones tomadas (véase 4.2.4), y f) revisar la eficacia de las acciones correctivas tomadas. — printed p.16', verification_note='md-verified 2026-09-05 (§8.5.2, printed p.16) [VC]', verified_at=now() where id='6c20e1e0-8f15-471e-bbbd-7bdf2474bd6d' and verification_status not in ('verified_against_standard','corrected');
-- accion_preventiva
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe determinar acciones para eliminar las causas de no conformidades potenciales para prevenir su ocurrencia. Las acciones preventivas deben ser apropiadas a los efectos de los problemas potenciales. | Debe establecerse un procedimiento documentado para definir los requisitos para: a) determinar las no conformidades potenciales y sus causas, b) evaluar la necesidad de actuar para prevenir la ocurrencia de no conformidades, c) determinar e implementar las acciones necesarias, d) registrar los resultados de las acciones tomadas (véase 4.2.4), y e) revisar la eficacia de las acciones preventivas tomadas. — printed p.16', verification_note='md-verified 2026-09-05 (§8.5.3, printed p.16) [VC]', verified_at=now() where id='05e94a05-22a9-4d01-9154-0d48c4045c86' and verification_status not in ('verified_against_standard','corrected');

